def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 if v == 1 else v for v in row] for row in grid]
    walls = [[v not in (0, 1) for v in row] for row in grid]
    supported = set((h - 1, c) for c in range(w) if not walls[h - 1][c])
    for r in range(h):
        for c in range(w):
            if not walls[r][c] and (r + 1 == h or walls[r + 1][c]):
                supported.add((r, c))

    added = True
    while added:
        added = False
        for r, c in sorted(supported):
            for dr, dc in ((0, -1), (0, 1), (-1, 0)):
                p = (r + dr, c + dc)
                if 0 <= p[0] < h and 0 <= p[1] < w and not walls[p[0]][p[1]] and p not in supported:
                    supported.add(p)
                    added = True

    n = sum(v == 1 for row in grid for v in row)
    chosen = set()
    candidates = sorted(supported, key=lambda p: (-p[0], p[1]))
    for p in candidates:
        if len(chosen) == n:
            break
        chosen.add(p)
        if p[0] > 0 and (p[0] - 1, p[1]) in supported:
            candidates.append((p[0] - 1, p[1]))
            candidates.sort(key=lambda p: (-p[0], p[1]))
    for r, c in chosen:
        out[r][c] = 1
    return out
